package dev.wowforever.importer.setup;
import static org.assertj.core.api.Assertions.*;
import dev.wowforever.importer.acquisition.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.function.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
/** Authored orchestration fixtures; these do not establish real-data projection or runtime-export acceptance. */
class LibraryPreparationWorkflowTest {
 @TempDir Path temporary;
 SetupPlan plan(boolean hotfix){Set<SetupPlan.Source> sources=new HashSet<>(Set.of(SetupPlan.Source.QUESTIE,SetupPlan.Source.NATIVE_DATA));if(hotfix)sources.add(SetupPlan.Source.RAIDBOTS_HOTFIX);return new SetupPlan(sources,Set.of(SetupPlan.Acquisition.WAGO_EXPORT),Optional.of(Forever70450Bootstrap.wagoManifest().identity()),List.of(),SetupPlan.currentPins(sources));}
 LibraryPreparationWorkflow.Session session(LibraryPreparationWorkflow workflow,boolean hotfix)throws Exception{return workflow.begin(plan(hotfix),temporary.resolve("app"),Optional.of(Files.writeString(temporary.resolve("active.sqlite"),"existing library")),"sources",List.of());}
 @Test void unsupportedTransportAndBuildFailBeforeStagingOrNetwork()throws Exception{var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var p=plan(false);var cdn=new SetupPlan(p.sources(),Set.of(SetupPlan.Acquisition.BLIZZARD_CDN),p.nativeIdentity(),List.of(),p.sourcePins());assertThatThrownBy(()->w.begin(cdn,temporary.resolve("no-output"),Optional.empty(),"cdn",List.of())).hasMessageContaining("requires explicitly selected Wago");assertThat(temporary.resolve("no-output")).doesNotExist();var build=new SetupPlan(p.sources(),p.acquisitions(),Optional.of(new SetupPlan.NativeIdentity("wow_classic_beta","1.60.1.70425","enUS")),List.of(),p.sourcePins());assertThatThrownBy(()->w.preflight(build)).hasMessageContaining("70450");assertThat(ops.calls).isEmpty();}
 @Test void explicitExtraPermissionsArePreservedButDoNotSelectAnotherCatalogueTransport()throws Exception{
  var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var p=plan(false);Path game=Files.createDirectory(temporary.resolve("WoW"));Path sentinel=Files.writeString(game.resolve("game-file"),"read only");
  var allowed=new SetupPlan(p.sources(),Set.of(SetupPlan.Acquisition.WAGO_EXPORT,SetupPlan.Acquisition.LOCAL_INSTALLATION,SetupPlan.Acquisition.BLIZZARD_CDN),p.nativeIdentity(),List.of(game),p.sourcePins());
  assertThat(w.review(allowed).warnings()).anyMatch(v->v.contains("selected Wago")&&v.contains("does not extract")&&v.contains("preserved"));
  var session=w.begin(allowed,temporary.resolve("owned"),Optional.empty(),"extra-permissions",List.of());var result=w.prepare(session,()->false,v->{});
  assertThat(result.plan().acquisitions()).containsExactlyInAnyOrderElementsOf(allowed.acquisitions());assertThat(result.plan().localGameRoots()).containsExactly(game);assertThat(ops.calls).containsExactly("community","native","catalogue","runtime");assertThat(result.acquisition().hotfix()).isEmpty();assertThat(sentinel).hasContent("read only");
 }
 @Test void allowedLocalFolderRemainsProtectedAndLocalOnlyCannotStartCatalogue()throws Exception{
  var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var p=plan(false);Path game=Files.createDirectory(temporary.resolve("selected-WoW"));
  var localOnly=new SetupPlan(p.sources(),Set.of(SetupPlan.Acquisition.LOCAL_INSTALLATION),p.nativeIdentity(),List.of(game),p.sourcePins());assertThatThrownBy(()->w.begin(localOnly,temporary.resolve("no-output"),Optional.empty(),"local-only",List.of())).hasMessageContaining("requires explicitly selected Wago");assertThat(temporary.resolve("no-output")).doesNotExist();
  var withWago=new SetupPlan(p.sources(),Set.of(SetupPlan.Acquisition.LOCAL_INSTALLATION,SetupPlan.Acquisition.WAGO_EXPORT),p.nativeIdentity(),List.of(game),p.sourcePins());assertThatThrownBy(()->w.begin(withWago,game.resolve("cache"),Optional.empty(),"inside-game",List.of())).hasMessageContaining("read-only");assertThat(game.resolve("cache")).doesNotExist();assertThat(ops.calls).isEmpty();
 }
 @Test void staleSourcePinFailsPreflight(){var w=new LibraryPreparationWorkflow(new Fake());var p=plan(false);var stale=new SetupPlan(p.sources(),p.acquisitions(),p.nativeIdentity(),List.of(),Map.of(SetupPlan.Source.QUESTIE,"a".repeat(40)));assertThatThrownBy(()->w.preflight(stale)).hasMessageContaining("pins changed");}
 @Test void nativeOnlyReviewExplainsKnownCoverageWithoutSelectingAnotherSource()throws Exception{var w=new LibraryPreparationWorkflow(new Fake());assertThat(w.review(plan(false)).warnings()).anyMatch(s->s.contains("73%")&&s.contains("85%"));assertThat(w.review(plan(true)).warnings()).noneMatch(s->s.contains("73%"));assertThat(plan(false).sources()).doesNotContain(SetupPlan.Source.RAIDBOTS_HOTFIX);}
 @Test void unselectedHotfixNeverCallsItsAcquisitionSchemaOrOverlay()throws Exception{var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var s=session(w,false);var result=w.prepare(s,()->false,p->{});assertThat(ops.calls).containsExactly("community","native","catalogue","runtime");assertThat(result.acquisition().hotfix()).isEmpty();assertThat(result.acquisition().schema()).isEmpty();assertThat(result.acquisition().overlay()).isEmpty();assertThat(Files.readString(temporary.resolve("active.sqlite"))).isEqualTo("existing library");assertThat(result.preparationReceipt()).exists();assertThat(Files.readString(result.preparationReceipt())).contains("activationPerformed=false","warningCount=");}
 @Test void explicitHotfixRunsOnlyItsDisclosedStagesAndReturnsReceipts()throws Exception{var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var s=session(w,true);List<LibraryPreparationWorkflow.Phase> phases=new ArrayList<>();var result=w.prepare(s,()->false,p->phases.add(p.phase()));assertThat(ops.calls).containsExactly("community","native","hotfix","schema","overlay","catalogue","runtime");assertThat(result.acquisition().overlay()).isPresent();assertThat(phases).containsSubsequence(LibraryPreparationWorkflow.Phase.HOTFIX,LibraryPreparationWorkflow.Phase.SCHEMA,LibraryPreparationWorkflow.Phase.OVERLAY,LibraryPreparationWorkflow.Phase.CATALOGUE,LibraryPreparationWorkflow.Phase.RUNTIME,LibraryPreparationWorkflow.Phase.READY);assertThat(result.warnings()).contains("Synthetic catalogue fixture; not real data acceptance");assertThat(Files.readString(result.catalogueJob().paths().directory().resolve("acquisition-report.properties"))).contains("completedDownloadBytes=", "raidbots.cacheReused=false", "schema.cacheReused=false");}
 @Test void retryPreservesSourceCacheAndCreatesFreshCatalogueJob()throws Exception{var ops=new Fake();ops.catalogueFailures=1;var w=new LibraryPreparationWorkflow(ops);var s=session(w,true);assertThatThrownBy(()->w.prepare(s,()->false,p->{})).hasMessageContaining("synthetic projection failure");var failed=s.lastCatalogueJob().orElseThrow();var result=w.prepare(s,()->false,p->{});assertThat(result.catalogueJob().paths().directory()).isNotEqualTo(failed.paths().directory());assertThat(ops.cacheJobs).allMatch(p->p.equals(s.acquisitionJob().paths().directory()));assertThat(s.acquisitionJob().paths().cache().resolve("fixture-native")).exists();assertThat(failed.paths().directory()).exists();assertThat(result.acquisition().hotfix().orElseThrow().reused()).isTrue();}
 @Test void retryAfterRuntimeFailureDoesNotReuseOrDeletePreviousCandidate()throws Exception{var ops=new Fake();ops.runtimeFailures=1;var w=new LibraryPreparationWorkflow(ops);var s=session(w,false);assertThatThrownBy(()->w.prepare(s,()->false,p->{})).hasMessageContaining("synthetic export failure");var first=s.lastCatalogueJob().orElseThrow();assertThat(first.paths().candidateDatabase()).exists();var result=w.prepare(s,()->false,p->{});assertThat(result.fullCandidate().database()).isNotEqualTo(first.paths().candidateDatabase());assertThat(first.paths().candidateDatabase()).exists();}
 @Test void cancellationAtNativeBoundaryDoesNotRunHiddenExtraStages()throws Exception{var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var s=session(w,true);AtomicBoolean stop=new AtomicBoolean();assertThatThrownBy(()->w.prepare(s,stop::get,p->{if(p.phase()==LibraryPreparationWorkflow.Phase.NATIVE_TABLES)stop.set(true);})).isInstanceOf(CancellationException.class);assertThat(ops.calls).containsExactly("community");assertThat(s.lastCatalogueJob()).isEmpty();}
 @Test void cancellationAfterCataloguePreservesFullCandidateWithoutStartingExport()throws Exception{var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var s=session(w,false);AtomicBoolean stop=new AtomicBoolean();assertThatThrownBy(()->w.prepare(s,stop::get,p->{if(p.phase()==LibraryPreparationWorkflow.Phase.RUNTIME)stop.set(true);})).isInstanceOf(CancellationException.class);assertThat(ops.calls).containsExactly("community","native","catalogue");assertThat(s.lastCatalogueJob().orElseThrow().paths().candidateDatabase()).exists();assertThat(Files.readString(temporary.resolve("active.sqlite"))).isEqualTo("existing library");}
 @Test void cancellationBeforeAttemptDoesNoBackendWork()throws Exception{var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var s=session(w,false);assertThatThrownBy(()->w.prepare(s,()->true,p->{})).isInstanceOf(CancellationException.class);assertThat(ops.calls).isEmpty();}
 @Test void changedPersistedPlanCannotReuseSessionOrContactProviders()throws Exception{var ops=new Fake();var w=new LibraryPreparationWorkflow(ops);var s=session(w,false);Files.writeString(s.acquisitionJob().paths().directory().resolve("preparation-plan.properties"),"version=wrong\n");assertThatThrownBy(()->w.prepare(s,()->false,p->{})).isInstanceOf(IOException.class);assertThat(ops.calls).isEmpty();}
 @Test void concurrentAttemptIsRejectedAndSessionUnlocksAfterFailure()throws Exception{var ops=new Fake();ops.entered=new CountDownLatch(1);ops.release=new CountDownLatch(1);var w=new LibraryPreparationWorkflow(ops);var s=session(w,false);var worker=Executors.newSingleThreadExecutor();try{var task=worker.submit(()->{try{return w.prepare(s,()->false,p->{});}catch(Exception e){throw new RuntimeException(e);}});assertThat(ops.entered.await(5,TimeUnit.SECONDS)).isTrue();assertThatThrownBy(()->w.prepare(s,()->false,p->{})).hasMessageContaining("already has a running");ops.release.countDown();assertThat(task.get(10,TimeUnit.SECONDS)).isNotNull();}finally{ops.release.countDown();worker.shutdownNow();}}
 static class Fake implements LibraryPreparationWorkflow.Operations {
  List<String> calls=new ArrayList<>();List<Path> cacheJobs=new ArrayList<>();int catalogueFailures,runtimeFailures;CountDownLatch entered,release;
  public CommunitySourceMaterializer.Result community(SetupPlan p,SetupPlan.JobContext j,BooleanSupplier c,Consumer<CommunitySourceMaterializer.Progress>x)throws Exception{calls.add("community");cacheJobs.add(j.paths().directory());if(entered!=null){entered.countDown();if(!release.await(5,TimeUnit.SECONDS))throw new IOException("fixture wait expired");}Path q=j.paths().cache().resolve("fixture-questie");Files.createDirectories(q);return new CommunitySourceMaterializer.Result(q,Optional.empty(),Optional.empty(),"community-fixture",true,0,List.of());}
  public WagoTableMaterializer.Result nativeTables(SetupPlan p,SetupPlan.JobContext j,WagoTableMaterializer.Manifest m,BooleanSupplier c,Consumer<WagoTableMaterializer.Progress>x)throws Exception{calls.add("native");Path dir=j.paths().cache().resolve("fixture-native");Files.createDirectories(dir);return new WagoTableMaterializer.Result(dir,"native-fixture",0,51,0);}
  public RaidbotsHotfixMaterializer.Result hotfix(SetupPlan.JobContext j,BooleanSupplier c,Consumer<RaidbotsHotfixMaterializer.Progress>x)throws Exception{calls.add("hotfix");Path file=j.paths().cache().resolve("fixture-raw");boolean reused=Files.exists(file);if(!reused)Files.writeString(file,"raw");return new RaidbotsHotfixMaterializer.Result(file,j.paths().cache().resolve("raw-proof"),null,reused);}
  public PinnedItemSparseDefinitionMaterializer.Result schema(SetupPlan.JobContext j,BooleanSupplier c,Consumer<PinnedItemSparseDefinitionMaterializer.Progress>x)throws Exception{calls.add("schema");Path file=j.paths().cache().resolve("fixture-schema");boolean reused=Files.exists(file);if(!reused)Files.writeString(file,"schema");return new PinnedItemSparseDefinitionMaterializer.Result(file,j.paths().cache().resolve("schema-proof"),reused);}
  public PinnedItemSparseOverlayMaterializer.Result overlay(SetupPlan.JobContext j,WagoTableMaterializer.Result b,WagoTableMaterializer.Manifest m,RaidbotsHotfixMaterializer.Result r,PinnedItemSparseDefinitionMaterializer.Result d,BooleanSupplier c,Consumer<PinnedItemSparseOverlayMaterializer.Progress>x){calls.add("overlay");return new PinnedItemSparseOverlayMaterializer.Result(j.paths().cache(),new PinnedItemSparseOverlayMaterializer.Validation("a".repeat(64),Set.of(8L),Set.of(5L),1));}
  public LibraryBuildJob.Candidate catalogue(SetupPlan p,SetupPlan.JobContext j,SetupPlan.MaterializedInputs i,BooleanSupplier c,Consumer<LibraryBuildJob.Progress>x)throws Exception{calls.add("catalogue");if(catalogueFailures-->0)throw new IOException("synthetic projection failure");Files.writeString(j.paths().candidateDatabase(),"synthetic candidate");Files.writeString(j.paths().archiveDatabase(),"synthetic archive");Path log=Files.writeString(j.paths().directory().resolve("synthetic.log"),"synthetic");return new LibraryBuildJob.Candidate(j.paths().candidateDatabase(),j.paths().archiveDatabase(),log,"b".repeat(64),new LibraryCandidateValidator.Validated("d".repeat(64),p.nativeIdentity().orElseThrow(),"e".repeat(64),Map.of(),List.of("Synthetic catalogue fixture; not real data acceptance")));}
  public RuntimeLibraryExporter.VerifiedExport runtime(LibraryBuildJob.Candidate candidate,SetupPlan.JobContext j,BooleanSupplier c,Consumer<LibraryPreparationWorkflow.Progress>x)throws Exception{calls.add("runtime");if(runtimeFailures-->0)throw new IOException("synthetic export failure");Path path=Files.writeString(j.paths().directory().resolve("runtime.sqlite"),"synthetic runtime");return new RuntimeLibraryExporter.VerifiedExport(candidate.database(),path,new RuntimeLibraryExporter.Receipt(Files.size(candidate.database()),candidate.sha256(),Files.size(path),"c".repeat(64),"d".repeat(64),0,0,Map.of()));}
 }
}
